interface PageProps {
  examId?: string;
}

export default function OMRTemplateContainer({ examId }: PageProps) {
  const [exam, setExam] = useState<LocalExam | null>(null);
  const [loading, setLoading] = useState(true);
  const [showPreview, setShowPreview] = useState(true);
  const [isClient, setIsClient] = useState(false);
  const [qrDataUrl, setQrDataUrl] = useState<string>('');
  const [omrCount, setOmrCount] = useState<number>(1);
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [progress, setProgress] = useState<{ current: number; total: number } | null>(null);

  const workerRef = useRef<Worker | null>(null);
  const id = examId || 'EXAM-3530';

  useEffect(() => {
    setIsClient(true);
    return () => {
      workerRef.current?.terminate();
    };
  }, []);

  useEffect(() => {
    async function fetchExamData() {
      try {
        const record = await db.exams.get(id);
        if (record) {
          setExam(record);
          
          const payload = JSON.stringify({
            examId: id,
            title: record.examTitle,
            questions: record.totalQuestions,
            duration: record.durationMinutes,
            platform: 'Examvia-LYSS'
          });

          const dataUrl = await QRCode.toDataURL(payload, {
            width: 200,
            margin: 1,
            color: {
              dark: '#0f172a',
              light: '#ffffff'
            }
          });
          setQrDataUrl(dataUrl);
        }
      } catch (error) {
        console.error('Failed to load exam details from IndexedDB:', error);
      } finally {
        setLoading(false);
      }
    }
    id && fetchExamData();
  }, [id]);

  const handleDownloadBatch = async () => {
    if (!exam || !qrDataUrl || isGenerating) return;

    const validCount = Math.min(Math.max(1, omrCount), 2000);
    setIsGenerating(true);
    setProgress({ current: 0, total: validCount });

    try {
      // 1. Render a single master page (~150ms) without serial number text
      const masterBlob = await pdf(
        <OMRMasterDocument exam={exam} examId={id} qrDataUrl={qrDataUrl} />
      ).toBlob();

      const masterBuffer = await masterBlob.arrayBuffer();

      // 2. Clone pages and stamp serial numbers off the main thread in the Web Worker
      workerRef.current?.terminate();
      const worker = new Worker(
        new URL('../workers/omrBatchWorker.ts', import.meta.url),
        { type: 'module' }
      );
      workerRef.current = worker;

      const finalBuffer = await new Promise<ArrayBuffer>((resolve, reject) => {
        worker.onmessage = (e: MessageEvent<WorkerResponse>) => {
          const msg = e.data;
          if (msg.type === 'PROGRESS') {
            setProgress({ current: msg.current, total: msg.total });
          } else if (msg.type === 'DONE') {
            resolve(msg.pdfBuffer);
          } else if (msg.type === 'ERROR') {
            reject(new Error(msg.message));
          }
        };

        worker.onerror = (err) => reject(err);

        const request: WorkerRequest = {
          templatePdfBuffer: masterBuffer,
          organizerName: ORGANIZER_NAME,
          examTitle: exam.examTitle,
          sheetCount: validCount,
        };

        // Transfer ownership of masterBuffer (zero-copy)
        worker.postMessage(request, [masterBuffer]);
      });

      const finalBlob = new Blob([finalBuffer], { type: 'application/pdf' });
      const url = URL.createObjectURL(finalBlob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `OMR_Sheets_Batch_${id}_${validCount}.pdf`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (error) {
      console.error('Failed to generate OMR PDF batch:', error);
    } finally {
      workerRef.current?.terminate();
      workerRef.current = null;
      setIsGenerating(false);
      setProgress(null);
    }
  };

  if (loading) {
    return (
      <main style={uiStyles.container}>
        <div style={uiStyles.card}>
          <p style={{ color: '#475569', fontSize: '14px', fontWeight: 600 }}>Loading Exam Blueprint from Local DB...</p>
        </div>
      </main>
    );
  }

  if (!exam) {
    return (
      <main style={uiStyles.container}>
        <div style={uiStyles.card}>
          <h1 style={uiStyles.heading}>Exam Blueprint Not Found</h1>
          <p style={{ color: '#64748b', fontSize: '14px' }}>No local exam record found matching ID: {id}</p>
        </div>
      </main>
    );
  }

  const sampleSerial = generateSerialNumber(ORGANIZER_NAME, exam.examTitle, 1);
  const progressPercent = progress
    ? Math.round((progress.current / progress.total) * 100)
    : 0;

  return (
    <main style={uiStyles.container}>
      <div style={uiStyles.card}>
        <h1 style={uiStyles.heading}>Exam OMR Verification Portal</h1>
        <p style={uiStyles.subHeading}>Secure Template Generation for Exam ID: <strong>{id}</strong></p>
        
        <div style={uiStyles.inputGroup}>
          <label htmlFor="omr-count" style={uiStyles.label}>Number of OMR Sheets to Design / Generate:</label>
          <input 
            id="omr-count"
            type="number" 
            min="1" 
            max="2000" 
            value={omrCount} 
            disabled={isGenerating}
            onChange={(e) => setOmrCount(Math.max(1, parseInt(e.target.value) || 1))}
            style={uiStyles.input}
          />
        </div>

        <div style={uiStyles.actionRow}>
          <button 
            onClick={() => setShowPreview(!showPreview)} 
            style={uiStyles.secondaryButton}
            disabled={isGenerating}
          >
            {showPreview ? 'Hide Live Preview' : 'Show Live Preview'}
          </button>

          {isClient && qrDataUrl ? (
            <button
              onClick={handleDownloadBatch}
              disabled={isGenerating}
              style={isGenerating ? uiStyles.buttonDisabled : uiStyles.button}
            >
              {isGenerating
                ? `Generating (${progress?.current ?? 0} / ${progress?.total ?? omrCount})...`
                : `Download ${omrCount} OMR Sheet(s) PDF`}
            </button>
          ) : (
            <button disabled style={uiStyles.buttonDisabled}>Loading PDF Generator...</button>
          )}
        </div>

        {isGenerating && progress && (
          <div style={uiStyles.progressWrapper}>
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px', fontWeight: 600, color: '#334155' }}>
              <span>Building OMR Batch...</span>
              <span>{progressPercent}%</span>
            </div>
            <div style={uiStyles.progressTrack}>
              <div style={{ ...uiStyles.progressFill, width: `${progressPercent}%` }} />
            </div>
          </div>
        )}

        {showPreview && isClient && qrDataUrl && (
          <div style={uiStyles.previewContainer}>
            <PDFViewer style={{ width: '100%', height: '750px', border: 'none' }}>
              <OMRMasterDocument
                exam={exam}
                examId={id}
                qrDataUrl={qrDataUrl}
                serialNumber={sampleSerial}
              />
            </PDFViewer>
          </div>
        )}
      </div>
    </main>
  );
}